const claim = $('DB — Reivindicar processamento').item.json;
const response = $json;
const nonEmpty = (value) => typeof value === 'string' && value.trim() !== '';
const strictPositiveSafeInteger = (value) => typeof value === 'number'
  && Number.isSafeInteger(value)
  && value > 0;
const nullableText = (value) => value === null
  || value === undefined
  || typeof value === 'string';
const nullableDuration = (value) => value === null
  || value === undefined
  || (typeof value === 'number'
    && Number.isFinite(value)
    && value >= 0);
const claimedId = typeof claim.id === 'number'
  ? claim.id
  : Number(claim.id);
const hasVideo = response.has_video === true
  || (Array.isArray(response.stream_types) && response.stream_types.includes('video'));
const downloadedAt = typeof response.downloaded_at === 'string'
  && Number.isFinite(Date.parse(response.downloaded_at));
const valid = response.success === true
  && strictPositiveSafeInteger(response.item_id)
  && response.item_id === claimedId
  && response.shortcode === claim.shortcode
  && nonEmpty(response.filename)
  && nonEmpty(response.mime_type)
  && nonEmpty(response.object_key)
  && nonEmpty(response.storage_provider)
  && nonEmpty(response.storage_bucket)
  && response.storage_provider === 'cloudflare_r2'
  && strictPositiveSafeInteger(response.file_size_bytes)
  && typeof response.sha256 === 'string'
  && /^[a-f0-9]{64}$/.test(response.sha256)
  && downloadedAt
  && nullableText(response.title)
  && nullableText(response.creator)
  && nullableText(response.caption)
  && nullableDuration(response.duration_seconds)
  && hasVideo;

if (!valid) {
  return {
    valid_response: false,
    failure_code: 'DOWNLOADER_INVALID_RESPONSE',
  };
}

return { ...response, valid_response: true };

const claim = $('DB — Reivindicar processamento').item.json;
const safeMessages = {
  DOWNLOAD_FAILED: 'Downloader could not acquire Reel media',
  DOWNLOADER_INTERNAL_ERROR: 'Downloader internal processing failed',
  DOWNLOADER_INVALID_RESPONSE: 'Downloader returned an invalid success response',
  DOWNLOADER_REQUEST_FAILED: 'Downloader request failed without a valid error envelope',
};
const parse = (value) => {
  let parsed = value;
  for (let depth = 0; depth < 3 && typeof parsed === 'string'; depth += 1) {
    try {
      parsed = JSON.parse(parsed);
    } catch {
      break;
    }
  }
  return parsed;
};
const candidates = [
  $json,
  $json.body,
  $json.error?.body,
  $json.error?.message,
  $json.error?.response?.body,
  $json.error?.response?.data,
].map(parse);
const envelope = candidates.find((value) => value && typeof value === 'object'
  && value.success === false
  && Number.isSafeInteger(Number(value.item_id))
  && Number(value.item_id) === Number(claim.id)
  && value.shortcode === claim.shortcode
  && typeof value.error?.code === 'string');
let code = $json.failure_code === 'DOWNLOADER_INVALID_RESPONSE'
  ? 'DOWNLOADER_INVALID_RESPONSE'
  : 'DOWNLOADER_REQUEST_FAILED';

if (envelope && Object.hasOwn(safeMessages, envelope.error.code)) {
  code = envelope.error.code;
}

return {
  reel_id: claim.id,
  shortcode: claim.shortcode,
  failure_code: code,
  error_message: safeMessages[code].slice(0, 512),
};
